CREATE OR REPLACE FUNCTION public.worker_put(p_world uuid, c creature, p_def text, p_count integer, p_ql double precision, p_x integer, p_y integer, p_extra text DEFAULT NULL::text, p_cast text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_at record; v_in boolean := false;
begin
